1	// Unicode predicates behind Python's str semantics.
2	//
3	// Node's RegExp Unicode property escapes expose the same category data
4	// CPython consults, so no tables need to be tabulated by hand here.
5	
6	const NON_PRINTABLE = /^[\p{Cc}\p{Cf}\p{Cs}\p{Co}\p{Cn}\p{Zl}\p{Zp}\p{Zs}]$/u;
7	const DECIMAL_DIGIT = /^\p{Nd}$/u;
8	const SPACE_SEPARATOR = /^\p{Zs}$/u;
9	
10	// The blanks int() strips from around a literal: the ASCII whitespace run,
11	// NEL, and the line/paragraph separators. Together with the Zs category below
12	// this is str.isspace() minus U+001C..U+001F, which int() rejects even though
13	// isspace() accepts them.
14	const INT_BLANKS = new Set([
15	  0x09, 0x0a, 0x0b, 0x0c, 0x0d, 0x20, 0x85, 0x2028, 0x2029,
16	]);
17	
18	// str.isprintable(): everything outside the C* and Z* categories, plus the
19	// space character itself, which is printable despite being Zs.
20	export function isPrintable(ch) {
21	  return ch === ' ' || !NON_PRINTABLE.test(ch);
22	}
23	
24	export function isIntWhitespace(ch) {
25	  return INT_BLANKS.has(ch.codePointAt(0)) || SPACE_SEPARATOR.test(ch);
26	}
27	
28	export function isDecimalDigit(ch) {
29	  return DECIMAL_DIGIT.test(ch);
30	}
31	
32	// Start of the maximal run of consecutive Nd code points containing `codePoint`,
33	// memoised because a run can be walked repeatedly while scanning one literal.
34	const runStarts = new Map();
35	
36	function decimalRunStart(codePoint) {
37	  const cached = runStarts.get(codePoint);
38	  if (cached !== undefined) return cached;
39	  let start = codePoint;
40	  while (start > 0 && DECIMAL_DIGIT.test(String.fromCodePoint(start - 1))) start -= 1;
41	  runStarts.set(codePoint, start);
42	  return start;
43	}
44	
45	// Each Nd block is ten consecutive code points running 0..9, and a run of
46	// digits is always a whole number of such blocks laid end to end — most runs
47	// hold one block, but the mathematical digits at U+1D7CE..U+1D7FF pack five
48	// adjacent blocks into a single fifty-code-point run. Taking the offset from
49	// the run's start modulo ten therefore gives the value in every case, whereas
50	// stopping at the first non-digit below would read the later blocks as zeros.
51	export function decimalDigitValue(ch) {
52	  const codePoint = ch.codePointAt(0);
53	  return (codePoint - decimalRunStart(codePoint)) % 10;
54	}
